const data = $input.first().json;

let output;

if (!data.found) {
  output = data.message;
} else {
  output = `MATCHED OBJECTION SCRIPT:
Script: ${data.best_script}
Follow-up question: ${data.followup_question || 'N/A'}
Success signal to watch for: ${data.success_signal || 'N/A'}

(${data.matches.length} similar objection${data.matches.length > 1 ? 's' : ''} found in total — use the best one above as your primary guide, adapt tone to the owner's message.)`;
}

return [{
  json: {
    tool_output: output
  }
}];

const results = $input.all()
  .map(i => i.json)
  .filter(r => r && Object.keys(r).length > 0);

if (results.length === 0) {
  return [{ json: {
    found: false,
    message: "No pre-written script matched this objection. Use your own judgement, tone, and general Dubai real estate knowledge to respond naturally and address the owner's concern."
  } }];
}

return [{ json: {
  found: true,
  matches: results,
  best_script: results[0].ai_script,
  followup_question: results[0].followup_question,
  success_signal: results[0].success_signal
} }];
